// v5: Parse Image Prompt - adapted for Meta-Llama-3.1-8B-Instruct
// LLaMA 3.1 does not emit <think> blocks; strip is kept as a harmless safety net.
// LLaMA 3.1 may prefix with "Here is the prompt:" or append "Note: I avoided..."
// Both are stripped below.
const response = $input.first().json;
const raw = (response.textResponse || response.text || response.message || '').trim();

if (!raw) throw new Error('Empty image prompt response from AnythingLLM / LLaMA 3.1');

// Strip Qwen3 think blocks (no-op for LLaMA, kept for safety)
let stripped = raw.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();

// Strip LLaMA 3.1 preamble patterns
stripped = stripped
  .replace(/^(here is the (image )?prompt[:\-]?\s*)/i, '')
  .replace(/^(image prompt:|prompt:|sure[!,]?\s*here[^:]*:\s*)/i, '')
  .replace(/```[\s\S]*?```/g, '')
  .trim();

// Strip trailing meta-commentary LLaMA may append after the prompt ends
const noteIdx = stripped.search(/\n\s*(note:|this prompt|i (have |)avoided|as (instructed|requested)|please note)/i);
if (noteIdx > 0) {
  stripped = stripped.substring(0, noteIdx).trim();
}

const imagePrompt = stripped;
if (!imagePrompt) throw new Error('Image prompt was empty after all cleanup');

return [{
  json: {
    chatId: $('Parse Content Response').first().json.chatId,
    topic: $('Parse Content Response').first().json.topic,
    caption: $('Parse Content Response').first().json.caption,
    hashtags: $('Parse Content Response').first().json.hashtags,
    visualStyle: $('Inject Randomness').first().json.visualStyle,
    imagePrompt
  }
}];

// v4: Save session AND update topic history for anti-repetition
const staticData = $getWorkflowStaticData('global');
const chatId = $('Parse Update').first().json.chatId;
const topic = $('Parse Content Response').first().json.topic;
const caption = $('Parse Content Response').first().json.caption;
const hashtags = $('Parse Content Response').first().json.hashtags;
const filename = $('Extract Image Filename').first().json.filename;

// Save session for approval flow
staticData[chatId] = { chatId, topic, caption, hashtags, filename };

// Track topic history (last 10 topics, persists across workflow runs)
let history = staticData.topicHistory || [];
history.unshift(topic);
if (history.length > 10) history = history.slice(0, 10);
staticData.topicHistory = history;

// Track format cycle position (persists across runs)
let cyclePos = staticData.formatCyclePos || 0;
staticData.formatCyclePos = cyclePos + 1;

return [{
  json: {
    chatId, topic, caption, hashtags, filename,
    telegramCaption: "<b>📋 TOPIC:</b> " + topic + "\n\n<b>📝 CAPTION:</b>\n" + caption + "\n\n<b>🏷️ HASHTAGS:</b>\n" + hashtags
  },
  binary: $input.first().binary
}];

const callbackData = $json.callbackData || '';
const chatId = $json.chatId;
const callbackQueryId = $json.callbackQueryId;
const parts = callbackData.split('_');
const action = parts[0];

if (!['approve', 'reject'].includes(action)) {
  throw new Error('Unknown callback: ' + callbackData);
}

return [{
  json: { action, chatId, callbackQueryId, isApprove: action === 'approve' }
}];

